const modelContext=document.modelContext;
if(modelContext?.registerTool){
  const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});
  const definitions=[
    {name:'read_practice_progress',title:'Leer progreso de práctica',description:'Lee el nivel, las monedas y los juegos del perfil local activo.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){const p=profile();if(!p)throw Error('Primero entra en un perfil.');return {level:level(p.xp),coins:p.coins,games:p.unlocked,verbs:db.verbs.length,completeList:db.completeList};}},
    {name:'start_verb_practice',title:'Empezar práctica de verbos',description:'Abre una práctica del juego Memoria activa para el perfil local activo; no responde preguntas ni concede monedas.',inputSchema:{type:'object',properties:{block:{type:'string',enum:['0','1','2','3','all','weak']}},required:['block'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['0','1','2','3','all','weak'].includes(input.block))throw Error('Bloque inválido.');const p=profile();if(!p?.pet||!p.testDone)throw Error('Completa primero el inicio.');if(p.tour<7)throw Error('Termina primero el tutorial.');if(!weakScope(input.block).length)throw Error('No hay verbos en esta selección.');startGame('recall',input.block);return {status:'started',questions:quiz.questions.length};}},
  ];
  for(const tool of definitions)try{Promise.resolve(modelContext.registerTool(tool,{signal:life.signal})).catch(()=>{});}catch{}
}


